(()=>{'use strict';const frame=document.getElementById('business-login-frame');if(!frame)return;const office='https://office.mowmatter.com';
// Only a click ID kept with analytics consent goes to Office; otherwise any earlier copy there is cleared.
function handOff(){const gclid=window.mmPrivacy?.allowed()===true?window.mmPrivacy.source?.().gclid:null;let time=Date.now();try{time=JSON.parse(localStorage.getItem('mm-privacy-v1')).time||time}catch{}frame.contentWindow?.postMessage(typeof gclid==='string'?{type:'mm-ad-click',gclid,consented_at:time}:{type:'mm-ad-click-clear'},office)}let handed=false;window.addEventListener('mmprivacychange',()=>{if(handed)handOff()});window.addEventListener('message',event=>{if(event.origin!==office||event.source!==frame.contentWindow)return;const data=event.data;if(!data||typeof data!=='object')return;if(data.type==='mm-business-login-height'&&!handed){handed=true;handOff()}if(data.type==='mm-business-login-height'&&Number.isFinite(data.height))frame.style.height=Math.min(1600,Math.max(300,data.height+32))+'px';else if(data.type==='mm-business-signup-submitted')window.mmAds?.convert('business_signup');else if(data.type==='mm-business-signed-in')location.assign('https://office.mowmatter.com/');else if(data.type==='mm-business-login-provider'&&['google','facebook'].includes(data.provider))location.assign('https://office.mowmatter.com/login.html?signin='+data.provider+'&launch_updates='+(data.launchUpdates===false?'0':'1'))})})();
